CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT,business_name TEXT NOT NULL,contact_name TEXT,phone TEXT,email TEXT,city TEXT,gstin TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT,order_ref TEXT NOT NULL UNIQUE,customer_id INTEGER,subtotal REAL NOT NULL,discount_rate REAL NOT NULL,discount_amount REAL NOT NULL,total REAL NOT NULL,status TEXT NOT NULL DEFAULT 'NEW',source TEXT NOT NULL DEFAULT 'WEBSITE',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,sku TEXT NOT NULL,product_name TEXT NOT NULL,qty INTEGER NOT NULL,unit_price REAL,line_total REAL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE INDEX IF NOT EXISTS idx_orders_created_at ON orders(created_at);
CREATE INDEX IF NOT EXISTS idx_order_items_sku ON order_items(sku);
